// Nodo de formato de HTML para el email
return [{
  json: {
    html: (() => {
      // 1) Recoger y filtrar items combinados (oferta + scoring)
      const items = $input.all().map(i => i.json).filter(j => j && Object.keys(j).length);

      // 2) Mostrar mensaje si no hay vacantes
      if (!items.length) {
        return `
          <table width="100%" cellpadding="0" cellspacing="0"
                 style="font-family:Arial,sans-serif;color:#333;background:#fff;">
            <tr>
              <td style="padding:20px;">
                <p style="font-size:16px;color:#1a73e8;">
                  No se encontraron vacantes disponibles.
                </p>
              </td>
            </tr>
          </table>
        `;
      }

      // 3) Ordenar vacantes de mayor a menor match_score
      items.sort((a, b) => (b.message?.content?.match_score || 0) - (a.message?.content?.match_score || 0));

      // 4) Obtener feedback y perfiles del análisis de CV
      const feedback = $('AI Agent').first().json.output.cv_feedback || {};
      const firstName= $('AI Agent').first().json.output.first_name;

      // 5) Normalizar fortalezas y mejoras
      const strengthsArr = Array.isArray(feedback.strengths)
        ? feedback.strengths
        : [feedback.strengths || 'Sin fortalezas'];
      const improvementsArr = Array.isArray(feedback.improvements)
        ? feedback.improvements
        : [feedback.improvements || 'Sin sugerencias'];

      const strengths = strengthsArr
        .map(s => `<tr><td style="padding:4px 0;font-size:14px;">• ${s}</td></tr>`)
        .join('');
      const improvements = improvementsArr
        .map(i => `<tr><td style="padding:4px 0;font-size:14px;">• ${i}</td></tr>`)
        .join('');
      const rewritten = feedback.suggested_rewrite || 'Sin datos';

      // 6) Lista de perfiles usados para búsqueda
      const profilesList = $('AI Agent').first().json.output.profiles.map(p => `
          <tr>
            <td style="padding:2px 0;font-size:14px;">
              • <strong>${p.Query}</strong> – ${p.Location || 'Ubicación no especificada'} | ${p.Language}
            </td>
          </tr>
        `)
        .join('');

      // 7) Resumen de vacantes (TOC) con match_score resaltado
      const toc = items
        .map((job, idx) => {
          const score = job.message.content.match_score ?? 'N/A';
          return `
            <tr>
              <td style="padding:4px 0;font-size:14px;">
                ${idx+1}. ${job.job_title}
                <span style="
                  background-color:#fff9e5;
                  padding:2px 6px;
                  border-radius:4px;
                  color:#f5a623;
                  font-weight:bold;
                  margin-left:8px;
                ">${score}%</span>
              </td>
            </tr>
          `;
        })
        .join('');

      // 8) Detalle de cada vacante
      const content = items
        .map((job, idx) => {
          const {
            employer_logo,
            employer_name   = 'Empresa desconocida',
            job_title       = 'Sin título',
            job_location    = 'Ubicación no especificada',
            job_employment_type = 'Tipo no especificado',
            job_description = 'Sin descripción',
            job_posted_at,
            apply_options   = []
          } = job;

          const score = job.message.content.match_score ?? 'N/A';
          const matched = Array.isArray(job.message.content.matched_skills)
            ? job.message.content.matched_skills
            : [];
          const note = job.message.content.note || '';

          const descHtml = job_description.replace(/\n/g, '<br/>');
          const applyHtml = apply_options.length
            ? apply_options
                .map(opt => `
                  <a href="${opt.apply_link || '#'}" target="_blank" style="
                    display:inline-block;
                    padding:6px 8px;
                    font-size:13px;
                    border-radius:4px;
                    background-color:#1a73e8;
                    color:#fff;
                    text-decoration:none;
                    margin-right:4px;
                  ">
                    Postularse en ${opt.publisher}
                  </a>
                `)
                .join('')
            : '<p style="font-size:14px;margin:0;">Sin enlaces de postulación</p>';

          const scoreHtml = `
            <div style="
              background-color:#fff9e5;
              border:1px solid #f5a623;
              border-radius:6px;
              padding:10px;
              margin:12px 0;
            ">
              <p style="margin:0 0 6px 0;font-size:14px;color:#333;">
                <strong>Match:</strong> ${score}%
              </p>
              <p style="margin:0 0 8px 0;font-size:13px;color:#555;">
                ${note}
              </p>
              <p style="margin:0 0 8px 0;font-size:13px;color:#555;">
                Habilidades coincidentes:
                <ul style="margin:0 0 0 8px;font-size:13px;color:#555;">
                  ${matched.map(s => `<li style="margin:4px 0;">${s}</li>`).join('')}
                </ul>
              </p>
            </div>
          `;

          return `
            <table width="100%" cellpadding="0" cellspacing="0" style="
              border:1px solid #ddd;
              border-radius:8px;
              background:#f5f5f5;
              margin-bottom:20px;
              font-family:Arial,sans-serif;
            ">
              <tr>
                <td style="padding:15px;">

                  <p style="margin:0 0 8px 0;font-size:12px;color:#888;">
                    <strong>Vacante ${idx+1}</strong>
                  </p>
                  ${employer_logo
                    ? `<img src="${employer_logo}" alt="Logo" width="80" style="margin:8px 0;display:block;"/>`
                    : ''}
                  <p style="margin:4px 0;font-size:16px;color:#1a73e8;">
                    <strong>${employer_name}</strong>
                  </p>
                  <p style="margin:2px 0;font-size:15px;color:#333;">
                    <strong>${job_title}</strong>
                  </p>
                  <p style="margin:4px 0;font-size:14px;color:#555;">
                    📍 ${job_location}
                  </p>
                  <p style="margin:4px 0;font-size:14px;color:#555;">
                    💼 ${job_employment_type}
                  </p>                  
                  <p style="margin:4px 0;font-size:14px;color:#555;">
                    📅 Publicado: ${job_posted_at || 'sin datos'}
                  </p>                  
                  <div style="margin-top:12px;">${applyHtml}</div>

                  ${scoreHtml}

                  <p style="margin:8px 0;font-size:14px;color:#333;">
                    ${descHtml}
                  </p>  
                  <p style="margin:4px 0;font-size:11px;color:#555;">
                    ID ${job.job_id}
                  </p>                  
                </td>
              </tr>
            </table>
          `;
        })
        .join('');

      // 9) Ensamblaje final del email
      return `
        <table width="100%" cellpadding="0" cellspacing="0" style="
          font-family:Arial,sans-serif;
          color:#333;
          background:#fff;
        ">
          <tr>
            <td style="padding:20px;">

              <!-- Saludo e introducción -->
              <table width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:20px;">
                <tr>
                  <td style="padding-bottom:10px;font-size:16px;">Hola ${firstName},</td>
                </tr>
                <tr>
                  <td style="padding-bottom:15px;font-size:14px;">Aquí tienes el análisis de tu CV y los resultados de búsqueda de vacantes en tu ciudad.</td>
                </tr>
              </table>

              <!-- Análisis de CV -->
              <table width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:20px;">
                <tr>
                  <td style="font-size:18px;color:#1a73e8; padding-bottom:8px;border-bottom:2px solid #1a73e8;">Análisis de tu CV</td>
                </tr>
                <tr>
                  <td style="font-size:16px;color:#1a73e8;padding-top:12px;">Resúmen sugerido</td>
                </tr>
                <tr>
                  <td style="padding:8px 0;font-size:14px;">${rewritten}</td>
                </tr>
                <tr>
                  <td style="font-size:16px;color:#1a73e8;padding-top:12px;">Fortalezas</td>
                </tr>
                ${strengths}
                <tr>
                  <td style="font-size:16px;color:#1a73e8;padding-top:12px;">Áreas de mejora</td>
                </tr>
                ${improvements}
              </table>

              <!-- Datos usados para búsqueda -->
              <table width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:20px;">
                <tr>
                  <td style="font-size:18px;color:#1a73e8;border-bottom:2px solid #1a73e8;padding-bottom:8px;">Datos usados para búsqueda</td>
                </tr>
                ${profilesList}
              </table>

              <!-- Resumen de Vacantes -->
              <table width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:10px;">
                <tr>
                  <td style="font-size:18px;color:#1a73e8;border-bottom:2px solid #1a73e8;padding-bottom:8px;">Resumen de Vacantes</td>
                </tr>
                ${toc}
              </table>

              <!-- Tarjetas de Vacantes -->
              ${content}

            </td>
          </tr>
        </table>
      `;
    })()
  }
}];

// FunctionItem “Prepara para scoring”
// Este código extrae del campo 'job_description' la sección de requisitos
// que comience tras la palabra 'Requisitos:', leyendo cada línea que empiece
// con '-' o '•'. Crea un array 'required_skills' con esas entradas.
// Luego prepara el payload para el nodo de scoring incluyendo:
//  - job_title
//  - job_description
//  - cv_summary, cv_strengths, cv_improvements, cv_skills desde cv_feedback
//  - required_skills extraído automáticamente
return {
  json: (() => {
    const feedback = $json.cv_feedback || {};
    const desc = $json.job_description || '';
    const lines = desc.split("\n");
    let inReq = false;
    const required_skills = [];
    for (const line of lines) {
      const trimmed = line.trim();
      // Detecta el inicio de la sección "Requisitos:" (case-insensitive)
      if (/^Requisitos[:]?/i.test(trimmed)) {
        inReq = true;
        continue;
      }
      if (inReq) {
        // Si la línea empieza con viñeta '-' o '•', extrae el texto
        const match = trimmed.match(/^[\-•]\s*(.+)/);
        if (match) {
          required_skills.push(match[1]);
        }
        // Si encuentra una línea en blanco o que no tiene viñeta, asume fin de sección
        else if (!trimmed) {
          break;
        }
      }
    }

    return {
      job_id:          $json.job_id,
      job_title:        $json.job_title || '',
      job_description:  desc,
      cv_summary:       feedback.suggested_rewrite || 'Sin resumen disponible',
      cv_strengths:     Array.isArray(feedback.strengths) ? feedback.strengths : (feedback.strengths ? [feedback.strengths] : []),
      cv_improvements:  Array.isArray(feedback.improvements) ? feedback.improvements : (feedback.improvements ? [feedback.improvements] : []),
      cv_skills:        Array.isArray(feedback.skills) ? feedback.skills : (feedback.skills ? [feedback.skills] : []),
      required_skills  // Array con los requisitos extraídos o vacío si no se detectó la sección
    };
  })()
};

// Primero, recuperamos todos los items de entrada
const items = $input.all();

// 1) Extraer feedback del CV
const cvItem = items.find(i => i.json.cv_feedback)?.json.cv_feedback || {};

// 2) Recolectar y aplanar todos los arrays `data` de las búsquedas
const allJobs = items
  .filter(i => Array.isArray(i.json.data))
  .flatMap(i => i.json.data);

// 3) Devolver un item por cada vacante, embebiendo el cv_feedback
return allJobs.map(job => ({
  json: {
    ...job,
    cv_feedback: cvItem
  }
}));

parameters.inputSchema:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "properties": {
    "first_name": {
      "type": ["string", "null"],
      "description": "El primer nombre del candidato, o null si no puede inferirse"
    },
    "profiles": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "Query": { "type": "string" },
          "Country": { "type": "string" },
          "Language": { "type": "string" },
          "Job_requirements": { "type": "string" },
          "Location": { "type": "string" }
        },
        "required": ["Query", "Country", "Language", "Job_requirements", "Location"],
        "additionalProperties": false
      }
    },
    "cv_feedback": {
      "type": "object",
      "properties": {
        "strengths": {
          "type": "array",
          "items": { "type": "string" }
        },
        "improvements": {
          "type": "array",
          "items": { "type": "string" }
        },
        "suggested_rewrite": { "type": "string" },
        "skills": {
          "type": "array",
          "items": { "type": "string" }
        }
      },
      "required": ["strengths", "improvements", "suggested_rewrite", "skills"],
      "additionalProperties": false
    }
  },
  "required": ["first_name", "profiles", "cv_feedback"],
  "additionalProperties": false
}
